63	// handleUpgradeResponse switches protocols and proxies the upgraded stream.
64	// Unless the stream is detached from the request, it returns once the
65	// stream has ended.
66	func (h *Handler) handleUpgradeResponse(logger *zap.Logger, rw http.ResponseWriter, req *http.Request, res *http.Response) {
67		reqUpType := upgradeType(req.Header)
68		resUpType := upgradeType(res.Header)
69	
70		// Taken from https://github.com/golang/go/commit/5c489514bc5e61ad9b5b07bd7d8ec65d66a0512a
71		// We know reqUpType is ASCII, it's checked by the caller.
72		if !asciiIsPrint(resUpType) {
73			if c := logger.Check(zapcore.DebugLevel, "backend tried to switch to invalid protocol"); c != nil {
74				c.Write(zap.String("backend_upgrade", resUpType))
75			}
76			return
77		}
78		if !asciiEqualFold(reqUpType, resUpType) {
79			if c := logger.Check(zapcore.DebugLevel, "backend tried to switch to unexpected protocol via Upgrade header"); c != nil {
80				c.Write(
81					zap.String("backend_upgrade", resUpType),
82					zap.String("requested_upgrade", reqUpType),
83				)
84			}
85			return
86		}
87	
88		backConn, ok := res.Body.(io.ReadWriteCloser)
89		if !ok {
90			logger.Error("internal error: 101 switching protocols response with non-writable body")
91			return
92		}
93	
94		// write header first, response headers should not be counted in size
95		// like the rest of handler chain.
96		copyHeader(rw.Header(), res.Header)
97		normalizeWebsocketHeaders(rw.Header())
98	
99		var (
100			conn io.ReadWriteCloser
101			brw  *bufio.ReadWriter
102			isH2 bool
103		)
104		// websocket over http2 or http3 if extended connect is enabled, assuming backend doesn't support this, the request will be modified to http1.1 upgrade
105		// TODO: once we can reliably detect backend support this, it can be removed for those backends
106		if body, ok := caddyhttp.GetVar(req.Context(), "extended_connect_websocket_body").(io.ReadCloser); ok {
107			req.Body = body
108			rw.Header().Del("Upgrade")
109			rw.Header().Del("Connection")
110			delete(rw.Header(), "Sec-WebSocket-Accept")
111			rw.WriteHeader(http.StatusOK)
112	
113			if c := logger.Check(zap.DebugLevel, "upgrading connection"); c != nil {
114				c.Write(zap.Int("http_version", 2))
115			}
116	
117			//nolint:bodyclose
118			flushErr := http.NewResponseController(rw).Flush()
119			if flushErr != nil {
120				if c := h.logger.Check(zap.ErrorLevel, "failed to flush http2 websocket response"); c != nil {
121					c.Write(zap.Error(flushErr))
122				}
123				return
124			}
125			conn = h2ReadWriteCloser{req.Body, rw}
126			isH2 = true
127			// bufio is not needed, use minimal buffer
128			brw = bufio.NewReadWriter(bufio.NewReaderSize(conn, 1), bufio.NewWriterSize(conn, 1))
129		} else {
130			rw.WriteHeader(res.StatusCode)
131	
132			if c := logger.Check(zap.DebugLevel, "upgrading connection"); c != nil {
133				c.Write(zap.Int("http_version", req.ProtoMajor))
134			}
135	
136			var hijackErr error
137			//nolint:bodyclose
138			conn, brw, hijackErr = http.NewResponseController(rw).Hijack()
139			if errors.Is(hijackErr, http.ErrNotSupported) {
140				if c := h.logger.Check(zap.ErrorLevel, "can't switch protocols using non-Hijacker ResponseWriter"); c != nil {
141					c.Write(zap.String("type", fmt.Sprintf("%T", rw)))
142				}
143				return
144			}
145	
146			if hijackErr != nil {
147				if c := h.logger.Check(zap.ErrorLevel, "hijack failed on protocol switch"); c != nil {
148					c.Write(zap.Error(hijackErr))
149				}
150				return
151			}
152		}
153	
154		// the hijacked connection is wrapped by response recorders which track its
155		// size for the access log without synchronization; the stream may outlive
156		// the request, so copy bytes on the raw connection
157		if !isH2 {
158			conn = rawConn(conn)
159		}
160	
161		if h.StreamLogs != nil && h.StreamLogs.SkipHandshake {
162			caddyhttp.SetVar(req.Context(), caddyhttp.LogSkipVar, true)
163		}
164	
165		var upstream string
166		if di, ok := GetDialInfo(req.Context()); ok {
167			upstream = di.Upstream.String()
168		}
169	
170		// a detached stream outlives the config and the request: its HTTP/1.1
171		// handler returns right after the hijack, so the stream must not hold on
172		// to the handler or the request. HTTP/2 extended CONNECT streams are part
173		// of their request and keep the handler until they end.
174		async := h.StreamDetached && !isH2
175	
176		s := &upgradedStream{
177			user:       conn,
178			backend:    backConn,
179			bufferSize: h.StreamBufferSize,
180			timeout:    time.Duration(h.StreamTimeout),
181			upstream:   upstream,
182			logger:     logger,
183			account:    h.streamMetrics.begin(upstream),
184			level:      h.streamLogLevel,
185			brw:        brw,
186		}
187		s.closeLoggers = []*zap.Logger{h.logger}
188		if h.StreamLogs != nil && h.StreamLogs.LoggerName == streamLogsAccessLogger {
189			if loggers := caddyhttp.AccessLoggers(req); len(loggers) > 0 {
190				s.closeLoggers = loggers
191			}
192		}
193		if async {
194			s.logger = h.logger.With(zap.String("upstream", upstream))
195		}
196	
197		// Ensure the hijacked client connection, and the new connection established
198		// with the backend, are both closed in the event of a server shutdown. This
199		// is done by registering them. We also try to gracefully close connections
200		// we recognize as websockets.
201		// We need to make sure the client connection messages (i.e. to upstream)
202		// are masked, so we need to know whether the connection is considered the
203		// server or the client side of the proxy.
204		isWS := isWebsocket(req)
205		gracefulClose := func(conn io.ReadWriteCloser, isClient bool) func() error {
206			if isWS {
207				return func() error {
208					return writeCloseControl(conn, isClient)
209				}
210			}
211			return nil
212		}
213		if h.StreamDetached {
214			// detached streams are closed when their upstream is removed from the
215			// config, not when the handler is cleaned up
216			s.gracefulUser, s.gracefulBackend = gracefulClose(conn, false), gracefulClose(backConn, true)
217			s.onDone = detachedStreams.add(upstream, s)
218		} else {
219			deleteFrontConn := h.registerConnection(conn, gracefulClose(conn, false), s.markReloaded)
220			deleteBackConn := h.registerConnection(backConn, gracefulClose(backConn, true), s.markReloaded)
221			s.onDone = func() {
222				deleteFrontConn()
223				deleteBackConn()
224			}
225		}
226	
227		if async {
228			go s.run(nil)
229			return
230		}
231		s.run(req.Context().Done())
232	}
