270	// UnmarshalCaddyfile sets up the stream logs from Caddyfile tokens. Syntax:
271	//
272	//	stream_logs {
273	//	    skip_handshake
274	//	    logger_name access
275	//	    level       <level>
276	//	}
277	func (s *StreamLogs) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
278		for nesting := d.Nesting(); d.NextBlock(nesting); {
279			switch d.Val() {
280			case "skip_handshake":
281				if d.NextArg() {
282					return d.ArgErr()
283				}
284				s.SkipHandshake = true
285	
286			case "logger_name":
287				if !d.NextArg() {
288					return d.ArgErr()
289				}
290				s.LoggerName = d.Val()
291				if d.NextArg() {
292					return d.ArgErr()
293				}
294	
295			case "level":
296				if !d.NextArg() {
297					return d.ArgErr()
298				}
299				s.Level = d.Val()
300				if d.NextArg() {
301					return d.ArgErr()
302				}
303	
304			default:
305				return d.Errf("unrecognized subdirective: %s", d.Val())
306			}
307		}
308		return nil
309	}
