356	// closeForReload closes the connections of a stream which is detached
357	// from its config because its upstream was removed from the config.
358	func (s *upgradedStream) closeForReload() error {
359		s.markReloaded()
360		var err error
361		for _, oc := range []openConnection{
362			{conn: s.user, gracefulClose: s.gracefulUser},
363			{conn: s.backend, gracefulClose: s.gracefulBackend},
364		} {
365			if closeErr := oc.close(); closeErr != nil && err == nil {
366				err = closeErr
367			}
368		}
369		return err
370	}
