372	// run proxies the stream until it ends and accounts it. If reqDone is not
373	// nil, the backend is closed when it is closed.
374	func (s *upgradedStream) run(reqDone <-chan struct{}) {
375		result := streamResultClosed
376		defer func() {
377			s.user.Close()
378			s.backend.Close()
379			s.wg.Wait()
380			s.onDone()
381			if s.reloaded.Load() {
382				result = streamResultReload
383			}
384			s.finish(result)
385		}()
386	
387		if reqDone != nil {
388			// adopted from https://github.com/golang/go/commit/8bcf2834afdf6a1f7937390903a41518715ef6f5
389			// Ensure that the cancellation of a request closes the backend.
390			// See issue https://golang.org/issue/35559.
391			stop := make(chan struct{})
392			defer close(stop)
393			go func() {
394				select {
395				case <-reqDone:
396					s.backend.Close()
397				case <-stop:
398				}
399			}()
400		}
401	
402		if err := s.brw.Flush(); err != nil {
403			if c := s.logger.Check(zapcore.DebugLevel, "response flush"); c != nil {
404				c.Write(zap.Error(err))
405			}
406			result = streamResultError
407			return
408		}
409	
410		// There may be buffered data in the *bufio.Reader
411		// see: https://github.com/caddyserver/caddy/issues/6273
412		if buffered := s.brw.Reader.Buffered(); buffered > 0 {
413			data, _ := s.brw.Peek(buffered)
414			n, err := s.backend.Write(data)
415			s.toBackend.Add(int64(n))
416			if err != nil {
417				if c := s.logger.Check(zapcore.DebugLevel, "backConn write failed"); c != nil {
418					c.Write(zap.Error(err))
419				}
420				result = streamResultError
421				return
422			}
423		}
424	
425		spc := switchProtocolCopier{
426			user:       s.user,
427			backend:    s.backend,
428			wg:         &s.wg,
429			bufferSize: s.bufferSize,
430			sent:       &s.toBackend,
431			received:   &s.fromBackend,
432		}
433	
434		// setup the timeout if requested
435		var timeoutc <-chan time.Time
436		if s.timeout > 0 {
437			timer := time.NewTimer(s.timeout)
438			defer timer.Stop()
439			timeoutc = timer.C
440		}
441	
442		// when a stream timeout is encountered, no error will be read from errc
443		// a buffer size of 2 will allow both the read and write goroutines to send the error and exit
444		// see: https://github.com/caddyserver/caddy/issues/7418
445		errc := make(chan error, 2)
446		s.wg.Add(2)
447		go spc.copyToBackend(errc)
448		go spc.copyFromBackend(errc)
449	
450		// Wait for both directions to finish. A clean EOF in one direction is a
451		// half-close of that direction only, not the end of the tunnel: the copier
452		// propagates it to the destination with CloseWrite and reports nil, so the
453		// other direction is left open and pending bytes can still drain. Anything
454		// else ends the tunnel: a copy error, a failed CloseWrite, or errCopyDone
455		// when the destination has no write half to close.
456		//
457		// net/http/httputil expresses the same wait as:
458		//
459		//	err := <-errc
460		//	if err == nil {
461		//		err = <-errc
462		//	}
463		//
464		// which cannot be used verbatim here because this handler also selects on the
465		// stream timeout, so the wait is repeated inside that select instead. Both
466		// accept the same sequences; the loop only additionally lets the timeout win
467		// at either wait.
468		//
469		// See https://github.com/caddyserver/caddy/issues/8026, and the same class
470		// fixed upstream in net/http/httputil (https://go.dev/issue/35892).
471		for range 2 {
472			select {
473			case err := <-errc:
474				if err != nil {
475					if c := s.logger.Check(zapcore.DebugLevel, "streaming error"); c != nil {
476						c.Write(zap.Error(err))
477					}
478					result = streamResultError
479					return
480				}
481			case time := <-timeoutc:
482				if c := s.logger.Check(zapcore.DebugLevel, "stream timed out"); c != nil {
483					c.Write(zap.Time("timeout", time))
484				}
485				result = streamResultTimeout
486				return
487			}
488		}
489	}
